```js
const queue = [];
let timer = null;

export function track(event) {
  queue.push({ ...event, ts: Date.now() });
  if (queue.length >= 20) flush();
  else if (!timer) timer = setTimeout(flush, 5000);
}

async function flush() {
  clearTimeout(timer);
  timer = null;
  if (!queue.length) return;
  await send([...queue]);
  queue.length = 0;
}
```

