function findMatch(rootA, rootB, target) {
  const path = [];
  for (let n = target; n !== rootA; n = n.parentElement) {
    path.push(Array.prototype.indexOf.call(n.parentElement.children, n));
  }
  let m = rootB;
  for (let i = path.length - 1; i >= 0; i--) m = m.children[path[i]];
  return m;
}
