function findMatch(rootA, rootB, target) {
  // visit every element of rootB in document order
  const walker = document.createTreeWalker(rootB, NodeFilter.SHOW_ELEMENT);
  for (let n = walker.currentNode; n; n = walker.nextNode()) {
    if (n.isEqualNode(target)) return n;
  }
  return null;
}
