function cx(...args) {
  const out = [];
  for (const a of args) {
    if (!a) continue;
    if (typeof a === 'string' || typeof a === 'number') out.push(a);
    else if (Array.isArray(a)) {
      const inner = cx(...a);
      if (inner) out.push(inner);
    } else if (typeof a === 'object') {
      for (const key of Object.keys(a)) if (a[key]) out.push(key);
    }
  }
  return out.join(' ');
}
